/**
 * Writes src/shared/build-info.ts — the commit and wall-clock time of this
 * build, so the Worker and the client both report the exact same release.
 *
 * Runs on `npm install` (postinstall) and before every build (prebuild), which
 * covers Cloudflare Builds too. The generated file is gitignored — never edit
 * it by hand and never commit it.
 *
 * This replaced the old APP_VERSION env/var plumbing: `wrangler deploy` on
 * Cloudflare Builds could not pass `--var`, so the Worker always answered
 * "dev" and the update banner never fired.
 */
import { writeFileSync, mkdirSync } from 'fs'
import { execSync } from 'child_process'
import { fileURLToPath } from 'url'
import { join, dirname } from 'path'

const root = join(dirname(fileURLToPath(import.meta.url)), '..')
const outFile = join(root, 'src/shared/build-info.ts')

function commitSha() {
  // Cloudflare Builds exports the commit; fall back to git, then to "dev".
  const fromCi = process.env.WORKERS_CI_COMMIT_SHA || process.env.CF_PAGES_COMMIT_SHA
  if (fromCi) return fromCi.slice(0, 7)
  try {
    return execSync('git rev-parse --short HEAD', { stdio: ['ignore', 'pipe', 'ignore'] })
      .toString()
      .trim()
  } catch {
    return 'dev'
  }
}

const sha = commitSha()
const epoch = Math.floor(Date.now() / 1000)

mkdirSync(dirname(outFile), { recursive: true })
writeFileSync(
  outFile,
  `// GENERATED by scripts/gen-build-info.mjs — do not edit, do not commit.
export const BUILD_SHA = '${sha}'
export const BUILD_EPOCH = ${epoch}
/** "<sha>-<unix-seconds>" — sorts chronologically, used for version compares. */
export const BUILD_VERSION = '${sha}-${epoch}'
export const BUILT_AT = '${new Date(epoch * 1000).toISOString()}'
`,
)

console.log(`build-info: ${sha}-${epoch}`)
